using System;using System.IO;using System.Reflection;
static class DelegatePoseReproduce {
 static string Show(float f)=>f.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" bits=0x"+BitConverter.ToInt32(BitConverter.GetBytes(f),0).ToString("X8");
 static int[] Ints(BinaryReader r,int n){var a=new int[n];for(int i=0;i<n;i++)a[i]=r.ReadInt32();return a;}
 static float[] Floats(BinaryReader r,int n){var a=new float[n];for(int i=0;i<n;i++)a[i]=r.ReadSingle();return a;}
 static int Main(string[] args){try{using(var r=new BinaryReader(File.OpenRead(args[0]))){if(r.ReadUInt32()!=0x31465346)throw new Exception("FSF1");int count=r.ReadInt32(),bones=r.ReadInt32(),poses=r.ReadInt32();if(poses!=1)throw new Exception("One actual pose only");var b=Ints(r,count*4);var w=Floats(r,count*4);var p=Floats(r,count*12);var rows=Floats(r,bones*4);if(r.BaseStream.Position!=r.BaseStream.Length)throw new Exception("Trailing fixture");Func<int,float[],float> evaluator=(index,rw)=>{float y=0;for(int k=0;k<4;k++){int q=index*4+k;if(w[q]==0)continue;int d=b[q]*4,n=q*3;y+=(rw[d]*p[n]+rw[d+1]*p[n+1]+rw[d+2]*p[n+2]+rw[d+3])*w[q];}return y;};var tree=new ExactFootFeatureBounds(bones,b,w,p,64,evaluator);ExactFootFeatureBounds.Statistics stats;float accelerated=tree.Minimum(rows,out stats);
 var exact=(Func<int,float[],float>)Delegate.CreateDelegate(typeof(Func<int,float[],float>),tree,typeof(ExactFootFeatureBounds).GetMethod("Exact",BindingFlags.Instance|BindingFlags.NonPublic));float leafMin=float.PositiveInfinity,brute=float.PositiveInfinity,staged=float.PositiveInfinity,wide=float.PositiveInfinity;int leafArg=-1,bruteArg=-1,stagedArg=-1,wideArg=-1;
 for(int i=0;i<count;i++){float leaf=exact(i,rows),sum=0,split=0,widened=0;for(int k=0;k<4;k++){int q=i*4+k;if(w[q]==0)continue;int d=b[q]*4,n=q*3;sum+=(rows[d]*p[n]+rows[d+1]*p[n+1]+rows[d+2]*p[n+2]+rows[d+3])*w[q];float value=rows[d]*p[n]+rows[d+1]*p[n+1]+rows[d+2]*p[n+2]+rows[d+3];split+=value*w[q];double wideDot=(double)rows[d]*p[n]+(double)rows[d+1]*p[n+1]+(double)rows[d+2]*p[n+2]+rows[d+3];widened=(float)((double)widened+wideDot*w[q]);}if(leaf<leafMin){leafMin=leaf;leafArg=i;}if(sum<brute){brute=sum;bruteArg=i;}if(split<staged){staged=split;stagedArg=i;}if(widened<wide){wide=widened;wideArg=i;}}
 Console.WriteLine("ACTUAL INPUT points="+count+" bones="+bones+" groups="+tree.GroupCount+" nodes="+tree.NodeCount);Console.WriteLine("BVH "+Show(accelerated)+" exactEvaluated="+stats.ExactPoints);Console.WriteLine("FULL_CORE_LEAF "+Show(leafMin)+" arg="+leafArg);Console.WriteLine("FULL_INDEPENDENT_SINGLE_EXPRESSION "+Show(brute)+" arg="+bruteArg);Console.WriteLine("FULL_STAGED_DOT "+Show(staged)+" arg="+stagedArg);Console.WriteLine("FULL_WIDENED_EXPRESSION_PROFILE "+Show(wide)+" arg="+wideArg);Console.WriteLine("BVH_equals_ALL_CORE_LEAF="+(accelerated==leafMin)+" BVH_equals_FULL_EXPRESSION="+(accelerated==brute));return accelerated==leafMin&&accelerated==brute?0:1;
 }}catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}
